//! Golden fixture for the v6 breakout rule.
//!
//! The fixture is a hand-derived table of level contexts and the decision the
//! rule must produce. It covers a long retest, a failed retest, a thin reward, a
//! broken-level exit, a short retest, and a missing support. The fixture is not
//! generated by the code under test.

use quantrule_backtest::context::{
    AgreementCode, AgreementContext, AxisContext, LadderContext, LevelContext, LevelView,
    ProgressionContext, StructureContext,
};
use quantrule_backtest::intent::StrategyPosition;
use quantrule_backtest::strategy::{
    Decision, EntryConfig, ExitConfig, ExitReason, LadderConfig, LadderWeights, LevelRetestConfig,
    Side, StopSpec, Strategy, StrategyConfig, StrategyInput, TargetSpec,
};

const FIXTURE: &str = include_str!("fixtures/breakout_golden.csv");
const HEADER: &str = "case,side,direction,momentum,structure,support,resistance,reference,broken_support,broken_resistance,position,expected_decision,expected_side,expected_stop,expected_target";

fn number(field: &str) -> Option<f64> {
    if field.is_empty() {
        None
    } else {
        Some(
            field
                .parse::<f64>()
                .unwrap_or_else(|error| panic!("invalid number {field:?}: {error}")),
        )
    }
}

fn side(field: &str) -> Side {
    match field {
        "long" => Side::Long,
        "short" => Side::Short,
        other => panic!("invalid side {other:?}"),
    }
}

fn axis(bullish: f64, bearish: f64, agreement: AgreementCode) -> AxisContext {
    AxisContext {
        timeframes: vec![3_600],
        bullish_count: u32::from(bullish > 0.0),
        bearish_count: u32::from(bearish > 0.0),
        neutral_count: u32::from(bullish == 0.0 && bearish == 0.0),
        weighted_value: Some(bullish - bearish),
        bullish_share: Some(bullish),
        bearish_share: Some(bearish),
        neutral_share: Some((1.0 - bullish - bearish).max(0.0)),
        agreement,
    }
}

fn level(price: Option<f64>, kind_code: i8) -> Option<LevelView> {
    price.map(|price| LevelView {
        timeframe_secs: 3_600,
        price,
        occurred_at: 0,
        available_at: 0,
        scale_code: 2,
        kind_code,
    })
}

fn config() -> StrategyConfig {
    StrategyConfig::new_breakout(
        LadderConfig::default(),
        LadderWeights::equal(1),
        EntryConfig::default(),
        ExitConfig::new_level(true, false, true).expect("the exit config is valid"),
        LevelRetestConfig::new(
            0.02,
            0.002,
            2.0,
            Some(quantrule_model::readings::PivotScale::Major),
        )
        .expect("the level config is valid"),
        true,
    )
    .expect("the strategy config is valid")
}

struct Flags {
    broken_support: Option<LevelView>,
    broken_resistance: Option<LevelView>,
}

fn context(
    side: Side,
    support: Option<LevelView>,
    resistance: Option<LevelView>,
    reference: f64,
    flags: Flags,
) -> LadderContext {
    let (direction, momentum, progression) = match side {
        Side::Long => (
            axis(1.0, 0.0, AgreementCode::Bullish),
            axis(0.5, 0.0, AgreementCode::Bullish),
            axis(1.0, 0.0, AgreementCode::Bullish),
        ),
        Side::Short => (
            axis(0.0, 1.0, AgreementCode::Bearish),
            axis(0.0, 0.5, AgreementCode::Bearish),
            axis(0.0, 1.0, AgreementCode::Bearish),
        ),
    };
    LadderContext {
        execution_timeframe_secs: 300,
        execution_bar_index: 0,
        execution_open_time: 0,
        execution_close_time: 300,
        context: Vec::new(),
        missing_timeframes: Vec::new(),
        direction,
        momentum,
        structure: StructureContext {
            score: AxisContext::unavailable(),
            conflict_count: 0,
        },
        progression: ProgressionContext {
            direction: progression,
            stage_histogram: [0.0; 6],
            late_or_terminal_count: 0,
        },
        levels: LevelContext {
            reference_price: Some(reference),
            support,
            resistance,
            support_distance_fraction: support.map(|level| (reference - level.price) / reference),
            resistance_distance_fraction: resistance
                .map(|level| (level.price - reference) / reference),
            broken_support: flags.broken_support,
            broken_resistance: flags.broken_resistance,
            ..LevelContext::unavailable()
        },
        agreement: AgreementContext::unavailable(),
    }
}

#[test]
fn the_breakout_golden_table_matches_the_rule() {
    let strategy = quantrule_backtest::strategy::LadderContextStrategy::new(config());
    let mut lines = FIXTURE.lines();
    assert_eq!(lines.next(), Some(HEADER), "fixture header changed");

    let mut rows = 0;
    for line in lines {
        let fields: Vec<&str> = line.split(',').collect();
        assert_eq!(fields.len(), 15, "wrong column count in {line:?}");
        let case = fields[0];
        let entry_side = side(fields[1]);
        let input = StrategyInput::new(
            300,
            0,
            0,
            number(fields[2]),
            number(fields[3]),
            number(fields[4]),
        );
        let support = level(number(fields[5]), -1);
        let resistance = level(number(fields[6]), 1);
        let reference = number(fields[7]).expect("the reference price is present");
        let context = context(
            entry_side,
            support,
            resistance,
            reference,
            Flags {
                broken_support: level(number(fields[8]), -1),
                broken_resistance: level(number(fields[9]), 1),
            },
        );
        let position = if fields[10] == "long" {
            StrategyPosition::opened(Side::Long, 0)
        } else {
            StrategyPosition::flat()
        };
        let decision = strategy.decide(&input, &context, position);
        match fields[11] {
            "hold" => assert_eq!(decision, Decision::Hold, "{case}"),
            "enter" => {
                let Decision::Enter(entry) = decision else {
                    panic!("{case}: expected an entry, got {decision:?}");
                };
                assert_eq!(entry.intent.side, side(fields[12]), "{case}");
                let StopSpec::Price { price: stop } = entry.intent.stop else {
                    panic!("{case}: expected a price stop");
                };
                let TargetSpec::Price { price: target } = entry.intent.target else {
                    panic!("{case}: expected a price target");
                };
                let expected_stop = number(fields[13]).expect("the expected stop is present");
                let expected_target = number(fields[14]).expect("the expected target is present");
                assert!((stop - expected_stop).abs() < 1e-9, "{case}: stop");
                assert!((target - expected_target).abs() < 1e-9, "{case}: target");
            }
            "exit" => {
                let Decision::Exit(exit) = decision else {
                    panic!("{case}: expected an exit, got {decision:?}");
                };
                assert_eq!(exit.side, side(fields[12]), "{case}");
                assert_eq!(exit.reason, ExitReason::LevelLost, "{case}");
            }
            other => panic!("{case}: unknown expected decision {other:?}"),
        }
        rows += 1;
    }
    assert_eq!(rows, 6, "fixture row count changed");
}
